import type { NextConfig } from "next";

/** Service detail pages in public/services/<slug>.html (generated by scripts/build-service-pages.mjs). */
const SERVICE_SLUGS = [
  "mobile-app-development",
  "web-application-development",
  "custom-software-development",
  "ui-ux-design",
  "backend-api-development",
  "ai-automation",
  "seo-digital-growth",
];

const nextConfig: NextConfig = {
  /* config options here */
  experimental: {
    agentFeedback: true,
  },
  cacheComponents: true,
  partialPrefetching: true,
  poweredByHeader: false,
  // One URL per page: the .html files are only reachable through the clean URLs below.
  async redirects() {
    const pages = ["about", "services", "projects", "technologies", "contact"];
    return [
      { source: "/index.html", destination: "/", permanent: true },
      ...pages.map((p) => ({ source: `/${p}.html`, destination: `/${p}`, permanent: true })),
      ...SERVICE_SLUGS.map((s) => ({ source: `/services/${s}.html`, destination: `/services/${s}`, permanent: true })),
    ];
  },
  async headers() {
    const security = [
      { key: "X-Content-Type-Options", value: "nosniff" },
      { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
      { key: "X-Frame-Options", value: "SAMEORIGIN" },
      { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(), browsing-topics=()" },
    ];
    return [
      { source: "/:path*", headers: security },
      // CSS/JS are stamped with ?v=<hash> by scripts/build-assets.mjs, so they can be cached for a year.
      { source: "/assets/:path*", headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }] },
      { source: "/:all*(webp|jpg|jpeg|png|svg|ico)", headers: [{ key: "Cache-Control", value: "public, max-age=2592000, stale-while-revalidate=86400" }] },
      { source: "/site.webmanifest", headers: [{ key: "Cache-Control", value: "public, max-age=86400" }] },
    ];
  },
  // Serve the static site pages in public/ at clean URLs.
  async rewrites() {
    const pages = ["about", "services", "projects", "technologies", "contact"];
    return {
      beforeFiles: [
        { source: "/", destination: "/index.html" },
        ...pages.map((p) => ({ source: `/${p}`, destination: `/${p}.html` })),
        ...SERVICE_SLUGS.map((s) => ({ source: `/services/${s}`, destination: `/services/${s}.html` })),
      ],
    };
  },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
